class Solution {
public:
    int numRollsToTarget(int n, int k, int target) {
        if (target < n || target > n * k) return 0;
        const int MOD = 1'000'000'007;
        vector<int> dp(target + 1, 0);
        dp[0] = 1;
        for (int d = 1; d <= n; ++d) {
            vector<int> nxt(target + 1, 0);
            for (int s = d; s <= min(target, d * k); ++s) {
                for (int f = 1; f <= min(k, s); ++f) {
                    nxt[s] = (nxt[s] + dp[s - f]) % MOD;
                }
            }
            dp = move(nxt);
        }
        return dp[target];
    }
};

class Solution {
    public int numRollsToTarget(int n, int k, int target) {
        if (target < n || target > n * k) return 0;
        final int MOD = 1_000_000_007;
        int[] dp = new int[target + 1];
        dp[0] = 1;
        for (int d = 1; d <= n; d++) {
            int[] nxt = new int[target + 1];
            for (int s = d; s <= Math.min(target, d * k); s++) {
                for (int f = 1; f <= Math.min(k, s); f++) {
                    nxt[s] = (nxt[s] + dp[s - f]) % MOD;
                }
            }
            dp = nxt;
        }
        return dp[target];
    }
}

